  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Melagatran, with a very high assay-transfer score of 0.9921, has human oral bioavailability of only 3–7%, directly supporting F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Saquinavir, with assay-transfer score 0.9904, has absolute oral bioavailability of 4% (range 1–9%) in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Olcegepant, with assay-transfer score 0.9895, has absolute oral bioavailability < 1%, strongly supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "FK3453, with assay-transfer score 0.9875, was discontinued for unexpectedly poor oral bioavailability attributed to AO-mediated clearance, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Astemizole, with assay-transfer score 0.9868, has estimated absolute oral bioavailability of about 3% in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "DX-9065a, with assay-transfer score 0.9825, has absolute human oral bioavailability of only 2–3%, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Danavorexton, with assay-transfer score 0.983, had poor oral bioavailability requiring IV infusion in clinical studies, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Didanosine, despite high transfer, showed fasting F of 0.22 (22%) at one dose, slightly above the threshold, but fed F was 0.17–0.19; this condition-dependent nucleoside result is the only near-threshold signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ibrutinib, an acrylamide-bearing pyrazolopyrimidine BTK inhibitor. The retrieved evidence, all with very high assay-transfer scores, overwhelmingly shows low absolute oral bioavailability (mostly <10%) across diverse chemotypes, supporting F < 20%. The single didanosine near-threshold signal is condition-dependent and outweighed by the consistent low-F evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Didanosine evidence is mixed around the threshold and strongly condition-dependent, limiting its weight.",
    "The retrieved analogues are diverse chemotypes; transfer relies on assay-transfer scores rather than direct structural similarity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

